#!/usr/bin/env node
const inquirer = import('inquirer');
const path = require('path');
const fs = require('fs');
const log = require('./scripts/log')
require('shelljs/global'); //

const fixConfig = require('./scripts/fixConfig');
const press = process.cwd();
const {ver, fixList, packages, des} = fixConfig;
const fixInfoPath = `${press}/fixed.json`;

//开始执行脚本
const runScripts = async () => {
    cd(press);
    //判断是否存在修复文件
    if (targetExists(fixInfoPath)) {
        //    读取修复文件
        const fixInfo = JSON.parse(fs.readFileSync(fixInfoPath).toString());
        if (fixInfo.ver === ver) {
            if (fixInfo.isFixed) {
                log('当前无需修复，修复程序即将退出！');
                exitProcess();
                return;
            }
        }
    }


    log(des);


    const questions = [
        {
            type: 'confirm',
            name: 'cancelFix',
            message: `是否进行修复程序`,
            default: false,
        }
    ];


    inquirer.then(async (res) => {
        res.default.prompt(questions).then(async (answers) => {

            if (!answers[`cancelFix`]) {
                log('已取消修复。');
                exitProcess();
            } else {
                const maxLength = fixList.length
                for (let i = 0; i < maxLength; i++) {
                    log(`正在执行第${i + 1}次任务,共${maxLength}次`)
                    const fixItem = fixList[i];
                    const {target, type, targetType, assets} = fixItem;
                    if (type === 'delete') {
                        const isExists = targetExists(target);
                        if (isExists) {
                            deleteTarget(target, targetType)
                        }
                    } else if (type === 'add') {
                        let res = await addTarget(assets, target, targetType);
                        if (!res) {
                            log(`${target}复制失败！！！`);
                            log('修复失败，修复程序即将退出！');
                            exitProcess();
                        }
                    } else if (type === 'replace') {


                        let res = await replaceTarget(assets, target, targetType);


                    }

                }
                updatePackage();

                createFixedFile();
            }
        });

    })


}


//退出程序
const exitProcess = () => {
    setTimeout(() => {
        process.exit();
    }, 500)
}
//    生成修复后文件
const createFixedFile = () => {
    const fileInfo = {
        ver,
        isFixed: true,
    }
    const targetPath = path.join(press, `/fixed.json`)
    fs.writeFileSync(targetPath, `${JSON.stringify(fileInfo)}`);
    log('修复成功！！！');
    exitProcess();
}


//修改package.json文件
const updatePackage = () => {
    const packageJson = path.join(press, `/package.json`);
    const _packages = JSON.parse(fs.readFileSync(packageJson).toString());

    for (const packagesKey in packages) {

        const {ver, type} = packages[`${packagesKey}`];


        if (type === 'replace') {
            _packages.dependencies[`${packagesKey}`] = ver;
        } else if (type === 'delete') {
            delete _packages.dependencies[`${packagesKey}`];

        }

    }

    fs.writeFileSync(packageJson, JSON.stringify(_packages));

}

//判断目标文件或文件夹是否存在
const targetExists = (name) => {
    return fs.existsSync(name);
}
//删除目标文件夹
const deleteTarget = (target, targetType) => {
    if (targetType === 'file') {
        fs.unlinkSync(target);
    } else {
        fs.rmSync(target, {recursive: true});
    }

}
//新增文件
const addTarget = (assets, target, targetType) => {
    return new Promise((resolve, reject) => {
        let assetsPath = path.join(__dirname, `./assets/${ver}/${assets}`);
        if (targetType === 'file') {


            //获取需要写入的文件名
            const writeName = path.basename(assetsPath)
            const targetPath = path.join(press, `/${target}/${writeName}`)
            fs.writeFileSync(targetPath, fs.readFileSync(assetsPath));
            resolve(true)
        } else if (targetType === 'fileDir') {
            const targetPath = path.join(press, `/${target}`);
            fs.cp(assetsPath, targetPath, {recursive: true}, (err) => {
                if (!err) {
                    resolve(true);
                } else {
                    reject(false);
                }
            });
        }
    })

}


//替换文件
const replaceTarget = (assets, target, targetType = 'file') => {

    return new Promise((resolve, reject) => {
        const isExists = targetExists(target);
        let assetsPath = path.join(__dirname, `./assets/${ver}/${assets}`);
        const targetPath = path.join(press, `/${target}`);
        //如果存在目标文件 执行删除
        if (isExists) {
            deleteTarget(target, 'file');
        }

        if (targetType === "file") {
            fs.writeFileSync(targetPath, fs.readFileSync(assetsPath));
            resolve(true);
        } else if (targetType === "fileDir") {
            fs.cp(assetsPath, targetPath, {recursive: true}, (err) => {
                if (!err) {
                    resolve(true);
                } else {
                    reject(false);
                }
            });
        }

    })

}

runScripts().then(res => {
    return ''
})

